use std::path::Path;

// No prelude as this is exported in the library and the prelude isn't
// for now.
use anyhow::Result;
use tracing::info;

pub const AF_PACKET_STUB: &str = "
%YAML 1.1
---

# Do not edit, automatically generated on every restart.

af-packet:
  - interface: default
    threads: auto
    cluster-id: 131
    tpacket-v3: yes
";

const EVEBOX_SERVER_SOCKET_CONFIG: &str = "# Generated by evectl. Do not edit.
input:
  enabled: true
  sockets:
    - path: /var/run/suricata/eve.sock
      type: unix_stream
      mode: \"0660\"
";

const EVEBOX_AGENT_SOCKET_CONFIG: &str = "# Generated by evectl. Do not edit.
input:
  sockets:
    - path: /var/run/suricata/eve.sock
      type: unix_stream
      mode: \"0660\"
";

pub fn write_af_packet_stub(path: &Path) -> Result<()> {
    info!("Writing af-packet partial to {}", path.display());
    std::fs::write(path, AF_PACKET_STUB)?;
    Ok(())
}

pub fn write_evebox_server_socket_config(path: &Path) -> Result<()> {
    write_evebox_socket_config(path, EVEBOX_SERVER_SOCKET_CONFIG)
}

pub fn write_evebox_agent_socket_config(path: &Path) -> Result<()> {
    write_evebox_socket_config(path, EVEBOX_AGENT_SOCKET_CONFIG)
}

fn write_evebox_socket_config(path: &Path, content: &str) -> Result<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, content)?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn writes_server_and_agent_socket_configs() {
        let dir = tempfile::tempdir().unwrap();
        let server = dir.path().join("server").join("evectl-input.yaml");
        let agent = dir.path().join("agent").join("evectl-input.yaml");

        write_evebox_server_socket_config(&server).unwrap();
        write_evebox_agent_socket_config(&agent).unwrap();

        let server = std::fs::read_to_string(server).unwrap();
        assert!(server.contains("enabled: true"));
        assert!(server.contains("type: unix_stream"));
        assert!(server.contains("mode: \"0660\""));

        let agent = std::fs::read_to_string(agent).unwrap();
        assert!(!agent.contains("enabled: true"));
        assert!(agent.contains("path: /var/run/suricata/eve.sock"));
    }
}
